        "L",
        "close_lost",
        _lost_reason_present,
        (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST")),
    ),
    (
        "Q",
        "L",
        "close_lost",
        _lost_reason_present,
        (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST")),
